import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-ejercicio42',
  templateUrl: './ejercicio42.component.html',
  styleUrls: ['./ejercicio42.component.css']
})
export class Ejercicio42Component implements OnInit{

  public maxPriceProduct: any;
  public customersWhoBoughtMostExpensiveProduct: string[] = [];

  constructor(private misComprasService: MisComprasService) { }

  ngOnInit(): void {
    this.misComprasService.obtenerCompras().subscribe((compras: any[]) => {
      this.findMostExpensiveProduct(compras);
    });
  }









}
